export type GearSlot =
  | 'head' | 'neck' | 'shoulder' | 'back' | 'chest'
  | 'wrist' | 'hands' | 'waist' | 'legs' | 'feet'
  | 'finger1' | 'finger2' | 'trinket1' | 'trinket2'
  | 'mainhand' | 'offhand' | 'ranged' | 'weapon';

export interface GearItem {
  slot: GearSlot;
  slotLabel: string;
  name: string;
  itemId: number;
  source: string;
  location: string;
  enchant?: string;
  stats?: string;
}

export interface SpecData {
  id: string;
  name: string;
  class: string;
  classId: string;
  role: 'DPS' | 'Tank' | 'Healer';
  statPriority: string;
  gear: GearItem[];
}

