export function getSpec(id: string): SpecData | undefined {
  return specs.find(s => s.id === id);
}

export const classesList = Array.from(new Set(specs.map(s => s.class))).sort();

export function specsByClass(cls: string): SpecData[] {
  return specs.filter(s => s.class === cls);
}
